use verus::prelude::*;

// Runtime helper mirroring the spec fn `precedence`
fn precedence_of(d: DType) -> u64 {
    match d {
        DType::Bool       => 0,
        DType::Int8       => 1,
        DType::Int16      => 2,
        DType::Int32      => 3,
        DType::Int64      => 4,
        DType::UInt8      => 5,
        DType::UInt16     => 6,
        DType::UInt32     => 7,
        DType::UInt64     => 8,
        DType::Float32    => 9,
        DType::Float64    => 10,
        DType::Complex64  => 11,
        DType::Complex128 => 12,
        DType::Object     => 13,
    }
}

// Runtime helper mirroring the spec fn `kind`
fn kind_of(d: DType) -> Kind {
    match d {
        DType::Bool       => Kind::BoolKind,
        DType::Int8
        | DType::Int16
        | DType::Int32
        | DType::Int64   => Kind::IntKind,
        DType::UInt8
        | DType::UInt16
        | DType::UInt32
        | DType::UInt64  => Kind::UIntKind,
        DType::Float32
        | DType::Float64 => Kind::FloatKind,
        DType::Complex64
        | DType::Complex128 => Kind::ComplexKind,
        DType::Object     => Kind::ObjectKind,
    }
}

// Task 1: find_max_precedence_type
fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // precondition (by spec): types.len() > 0
    let mut max = types[0];
    let mut i = 1;
    while i < types.len() {
        let t = types[i];
        if precedence_of(t) > precedence_of(max) {
            max = t;
        }
        i += 1;
    }
    max
}

// Task 2: find_common_type
fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    // precondition (by spec): array_types.len() > 0 || scalar_types.len() > 0
    if array_types.len() == 0 {
        // only scalars
        Some(find_max_precedence_type(scalar_types))
    } else if scalar_types.len() == 0 {
        // only arrays
        Some(find_max_precedence_type(array_types))
    } else {
        // both non-empty
        let ma = find_max_precedence_type(array_types);
        let ms = find_max_precedence_type(scalar_types);
        if kind_of(ma) == kind_of(ms) {
            Some(ma)
        } else {
            Some(ms)
        }
    }
}